// Minimal HTMX-compatible stub. Fixes: default target = element (not body), exposes htmx.ajax, fires htmx:afterSettle.
(function(){
  function swap(targetEl, html){
    targetEl.innerHTML = html;
    process(targetEl);
    document.body.dispatchEvent(new CustomEvent('htmx:afterSettle'));
  }

  function request(el, method, url){
    if(el.getAttribute('hx-confirm') && !confirm(el.getAttribute('hx-confirm'))) return;
    var targetSel = el.getAttribute('hx-target');
    var target    = targetSel ? document.querySelector(targetSel) : el;
    var options   = { method: method, headers: {'HX-Request':'true'} };
    if(method === 'POST' && el.tagName === 'FORM') options.body = new FormData(el);
    fetch(url, options)
      .then(function(r){ return r.text(); })
      .then(function(html){
        swap(target || el, html);
        if(method === 'POST' && el.tagName === 'FORM') el.reset();
      });
  }

  function triggersFor(el){
    var t = el.getAttribute('hx-trigger');
    if(!t) return ['default'];
    return t.split(',').map(function(p){ return p.trim().split(/\s+/)[0]; }).filter(Boolean);
  }

  function hasTrigger(el, name){ return triggersFor(el).indexOf(name) !== -1; }

  function shouldBindUserEvent(el){
    var triggers = triggersFor(el);
    return triggers.indexOf('default') !== -1 ||
           triggers.indexOf(el.tagName === 'FORM' ? 'submit' : 'click') !== -1;
  }

  function bind(el, attr, method){
    if(!shouldBindUserEvent(el) || el.dataset.htmxBound) return;
    el.dataset.htmxBound = 'true';
    el.addEventListener(el.tagName === 'FORM' ? 'submit' : 'click', function(evt){
      evt.preventDefault();
      evt.stopPropagation();
      request(el, method, el.getAttribute(attr));
    });
  }

  function process(root){
    root.querySelectorAll('[hx-get]').forEach(function(el){
      if(hasTrigger(el, 'load') && !el.dataset.htmxLoaded){
        el.dataset.htmxLoaded = 'true';
        request(el, 'GET', el.getAttribute('hx-get'));
      }
      bind(el, 'hx-get', 'GET');
    });
    root.querySelectorAll('[hx-post]').forEach(function(el){   bind(el, 'hx-post',   'POST');   });
    root.querySelectorAll('[hx-put]').forEach(function(el){    bind(el, 'hx-put',    'PUT');    });
    root.querySelectorAll('[hx-delete]').forEach(function(el){ bind(el, 'hx-delete', 'DELETE'); });
  }

  window.htmx = {
    ajax: function(method, url, opts){
      var targetSel = opts && opts.target;
      var target    = targetSel ? document.querySelector(targetSel) : document.body;
      if(!target) return;
      fetch(url, { method: method, headers: {'HX-Request':'true'} })
        .then(function(r){ return r.text(); })
        .then(function(html){ swap(target, html); });
    },
    process: process
  };

  document.addEventListener('DOMContentLoaded', function(){ process(document); });
})();
